START TRANSACTION;INSERT INTO admin_permissions(code,display_name) VALUES('pet.pendant.grant','펜던트 가방 지급') ON DUPLICATE KEY UPDATE display_name=VALUES(display_name);INSERT INTO admin_role_permissions(role_id,permission_code) SELECT id,'pet.pendant.grant' FROM admin_roles WHERE code='super_admin' ON DUPLICATE KEY UPDATE permission_code=VALUES(permission_code);INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('PENDANT_GRANT','pendant_grant','VERIFIED_USER','SHADOW',1,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),version=VALUES(version);INSERT INTO command_aliases(command_text,command_code,active) VALUES('/펜던트추가','PENDANT_GRANT',1) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=1;COMMIT;
